(function () {
    document.csnDebugQS ??= {};
    function checkQualtricsTrigger(e) {
        var metaData = e?.detail;
        if (!Array.isArray(metaData)) return;
        var entry = metaData.find(m => m?.type === "KeyValueMetaData" && m?.key === "debug/quick-search/variant");
        var variant = entry && entry.value;
        if (variant !== "on" && variant !== "off") return;
        document.csnDebugQS.variant = variant;
        window.removeEventListener("metaDataReady", checkQualtricsTrigger);
        setTimeout(function () {
            try {
                const api = window.QSI?.API;
                if (!api) return;
                api.unload();
                api.load().done(api.run);
            } catch (err) { /* Qualtrics deployment not present on page */ }
        }, 1000);
    }
    window.addEventListener("metaDataReady", checkQualtricsTrigger);
})();

(function () {
    var param = "s";
    var detailsPath = "/cars/details/";
    function isDetails(url) {
        return url.origin === location.origin && url.pathname.toLowerCase().indexOf(detailsPath) === 0;
    }
    var current = new URL(location.href);
    if (current.searchParams.get(param) !== "01a1ceb4-b426-7e05-98dc-681eefcab4a6") {
        current.searchParams.set(param, "01a1ceb4-b426-7e05-98dc-681eefcab4a6");
        history.replaceState(history.state, "", current.href);
    }
    if (window.csnSearchIdLinkListener) return;
    window.csnSearchIdLinkListener = true;
    function appendSearchId(e) {
        var page = new URL(location.href);
        var searchId = page.searchParams.get(param);
        if (!searchId || isDetails(page)) return;
        var link = e.target instanceof Element ? e.target.closest("a[href]") : null;
        if (!link) return;
        var target = new URL(link.href, location.href);
        if (!isDetails(target)) return;
        target.searchParams.set(param, searchId);
        link.href = target.href;
    }
    document.addEventListener("pointerdown", appendSearchId, true);
    document.addEventListener("keydown", appendSearchId, true);
})();
